window.VOL8_TESTS[1]={"id": 1, "module": "listening", "vol": 8, "sections": [{"number": 1, "html": "<p class=\"subheading\"><b>Questions 1–10</b></p><p class=\"instruction\">Complete the form below.</p><p class=\"instruction\">Write <b>NO MORE THAN TWO WORDS AND/OR A NUMBER</b> for each answer.</p><p class=\"\"><b>International Student Travel Agency Enquiry Form</b></p><p class=\"\">Name:                  Sarah Brown</p><p>Date of birth:       <span class=\"qnum\">1</span><input class=\"gap\" data-q=\"1\" aria-label=\"Câu 1\" autocomplete=\"off\" spellcheck=\"false\"></p><p class=\"\">Address:               21 Waverley Road, Radstone, RD4 6W</p><p>Contact tel. no.:    <span class=\"qnum\">2</span><input class=\"gap\" data-q=\"2\" aria-label=\"Câu 2\" autocomplete=\"off\" spellcheck=\"false\"></p><p class=\"\">Notes:</p><p>wants to travel in   <span class=\"qnum\">3</span><input class=\"gap\" data-q=\"3\" aria-label=\"Câu 3\" autocomplete=\"off\" spellcheck=\"false\"> Europe</p><p>hopes to travel by <span class=\"qnum\">4</span><input class=\"gap\" data-q=\"4\" aria-label=\"Câu 4\" autocomplete=\"off\" spellcheck=\"false\"></p><p>interested in working in a <span class=\"qnum\">5</span><input class=\"gap\" data-q=\"5\" aria-label=\"Câu 5\" autocomplete=\"off\" spellcheck=\"false\"></p><p>recommended to consider an alternative e.g.  <span class=\"qnum\">6</span><input class=\"gap\" data-q=\"6\" aria-label=\"Câu 6\" autocomplete=\"off\" spellcheck=\"false\">work</p><p>advised to buy a European <span class=\"qnum\">7</span><input class=\"gap\" data-q=\"7\" aria-label=\"Câu 7\" autocomplete=\"off\" spellcheck=\"false\"> for travelling</p><p>given a  <span class=\"qnum\">8</span><input class=\"gap\" data-q=\"8\" aria-label=\"Câu 8\" autocomplete=\"off\" spellcheck=\"false\">  with accommodation details</p><p>agreed to take out  <span class=\"qnum\">9</span><input class=\"gap\" data-q=\"9\" aria-label=\"Câu 9\" autocomplete=\"off\" spellcheck=\"false\">from the Agency</p><p>told to use an  <span class=\"qnum\">10</span><input class=\"gap\" data-q=\"10\" aria-label=\"Câu 10\" autocomplete=\"off\" spellcheck=\"false\">for contacting people</p>"}, {"number": 2, "html": "<p class=\"subheading\"><b>Questions 11–15</b></p><p class=\"instruction\">Label the map below.</p><p class=\"instruction\">Choose the correct letter, A-H, next to questions 11-15.</p><img class=\"source-image\" src=\"Listening%20-%20Vol%208/Test%201/image1.png\" alt=\"Hình gốc trong đề [VOL 8] LIS TEST 1\"><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> A</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> B</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> C</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> D</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> E</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> F</button><button class=\"token\" draggable=\"true\" data-token=\"G\"><b>G</b> G</button><button class=\"token\" draggable=\"true\" data-token=\"H\"><b>H</b> H</button></div><p class=\"matching-row\" data-drop=\"11\"><span class=\"qnum\">11</span>seating area <select class=\"answer-select\" data-q=\"11\" aria-label=\"Câu 11\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"12\"><span class=\"qnum\">12</span>cushions <select class=\"answer-select\" data-q=\"12\" aria-label=\"Câu 12\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"13\"><span class=\"qnum\">13</span>computer bench <select class=\"answer-select\" data-q=\"13\" aria-label=\"Câu 13\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"14\"><span class=\"qnum\">14</span>café bar <select class=\"answer-select\" data-q=\"14\" aria-label=\"Câu 14\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"15\"><span class=\"qnum\">15</span>newspapers <select class=\"answer-select\" data-q=\"15\" aria-label=\"Câu 15\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p>\n<p class=\"subheading\"><b>Questions 16–20</b></p><p class=\"instruction\">Choose the correct answer.</p><div data-render-choice=\"16\"></div><div data-render-choice=\"17\"></div><div data-render-choice=\"18\"></div><div data-render-choice=\"19\"></div><div data-render-choice=\"20\"></div>"}, {"number": 3, "html": "<p class=\"subheading\"><b>Questions 21–24</b></p><p class=\"instruction\">Choose the correct answer.</p><p class=\"\"><b>The Just-in-Time Supply System (JIT)</b></p><div data-render-choice=\"21\"></div><div data-render-choice=\"22\"></div><div data-render-choice=\"23\"></div><div data-render-choice=\"24\"></div>\n<p class=\"subheading\"><b>Questions 25–30</b></p><p class=\"instruction\"><i>What criticism is made of each of the following technical aspect of Ron&#x27;s presentation?</i></p><p class=\"instruction\">Choose <b>SIX</b> correct answers, <b>A-H</b>, next to questions <b>25-30.</b></p><p class=\"instruction\"><b>Technical aspects of presentation </b></p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> too informal</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> too irregular</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> too predictable</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> too sudden</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> too technical</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> too unenthusiastic</button><button class=\"token\" draggable=\"true\" data-token=\"G\"><b>G</b> too loosely related</button><button class=\"token\" draggable=\"true\" data-token=\"H\"><b>H</b> too vague</button></div><p class=\"matching-row\" data-drop=\"25\"><span class=\"qnum\">25</span>speed of delivery <select class=\"answer-select\" data-q=\"25\" aria-label=\"Câu 25\"><option value=\"\">Chọn</option><option value=\"A\">A · too informal</option><option value=\"B\">B · too irregular</option><option value=\"C\">C · too predictable</option><option value=\"D\">D · too sudden</option><option value=\"E\">E · too technical</option><option value=\"F\">F · too unenthusiastic</option><option value=\"G\">G · too loosely related</option><option value=\"H\">H · too vague</option></select></p><p class=\"matching-row\" data-drop=\"26\"><span class=\"qnum\">26</span>purpose <select class=\"answer-select\" data-q=\"26\" aria-label=\"Câu 26\"><option value=\"\">Chọn</option><option value=\"A\">A · too informal</option><option value=\"B\">B · too irregular</option><option value=\"C\">C · too predictable</option><option value=\"D\">D · too sudden</option><option value=\"E\">E · too technical</option><option value=\"F\">F · too unenthusiastic</option><option value=\"G\">G · too loosely related</option><option value=\"H\">H · too vague</option></select></p><p class=\"matching-row\" data-drop=\"27\"><span class=\"qnum\">27</span>transitions <select class=\"answer-select\" data-q=\"27\" aria-label=\"Câu 27\"><option value=\"\">Chọn</option><option value=\"A\">A · too informal</option><option value=\"B\">B · too irregular</option><option value=\"C\">C · too predictable</option><option value=\"D\">D · too sudden</option><option value=\"E\">E · too technical</option><option value=\"F\">F · too unenthusiastic</option><option value=\"G\">G · too loosely related</option><option value=\"H\">H · too vague</option></select></p><p class=\"matching-row\" data-drop=\"28\"><span class=\"qnum\">28</span>visuals <select class=\"answer-select\" data-q=\"28\" aria-label=\"Câu 28\"><option value=\"\">Chọn</option><option value=\"A\">A · too informal</option><option value=\"B\">B · too irregular</option><option value=\"C\">C · too predictable</option><option value=\"D\">D · too sudden</option><option value=\"E\">E · too technical</option><option value=\"F\">F · too unenthusiastic</option><option value=\"G\">G · too loosely related</option><option value=\"H\">H · too vague</option></select></p><p class=\"matching-row\" data-drop=\"29\"><span class=\"qnum\">29</span>vocabulary <select class=\"answer-select\" data-q=\"29\" aria-label=\"Câu 29\"><option value=\"\">Chọn</option><option value=\"A\">A · too informal</option><option value=\"B\">B · too irregular</option><option value=\"C\">C · too predictable</option><option value=\"D\">D · too sudden</option><option value=\"E\">E · too technical</option><option value=\"F\">F · too unenthusiastic</option><option value=\"G\">G · too loosely related</option><option value=\"H\">H · too vague</option></select></p><p class=\"matching-row\" data-drop=\"30\"><span class=\"qnum\">30</span>body language <select class=\"answer-select\" data-q=\"30\" aria-label=\"Câu 30\"><option value=\"\">Chọn</option><option value=\"A\">A · too informal</option><option value=\"B\">B · too irregular</option><option value=\"C\">C · too predictable</option><option value=\"D\">D · too sudden</option><option value=\"E\">E · too technical</option><option value=\"F\">F · too unenthusiastic</option><option value=\"G\">G · too loosely related</option><option value=\"H\">H · too vague</option></select></p>"}, {"number": 4, "html": "<p class=\"subheading\"><b>Questions 31–40</b></p><p class=\"instruction\">Complete the notes below.</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> for each answer.</p><p class=\"\"><b>Dyscalculia</b></p><p>Teaching applied in class <span class=\"qnum\">31</span><input class=\"gap\" data-q=\"31\" aria-label=\"Câu 31\" autocomplete=\"off\" spellcheck=\"false\">  method of teaching<br>Children have difficulty to learn the concept of  <span class=\"qnum\">32</span><input class=\"gap\" data-q=\"32\" aria-label=\"Câu 32\" autocomplete=\"off\" spellcheck=\"false\">    and sequence<br>In the class, they are taught everyday practice / problem e.g. dealing with  <span class=\"qnum\">33</span><input class=\"gap\" data-q=\"33\" aria-label=\"Câu 33\" autocomplete=\"off\" spellcheck=\"false\"> <br>For children with mathematics disorder, they should develop more calculation to develop more  <span class=\"qnum\">34</span><input class=\"gap\" data-q=\"34\" aria-label=\"Câu 34\" autocomplete=\"off\" spellcheck=\"false\">  <br>Solution : teachers encourage them to solve the problem of by <span class=\"qnum\">35</span><input class=\"gap\" data-q=\"35\" aria-label=\"Câu 35\" autocomplete=\"off\" spellcheck=\"false\"> Do exercises e.g. breathing , relaxation and   <span class=\"qnum\">36</span><input class=\"gap\" data-q=\"36\" aria-label=\"Câu 36\" autocomplete=\"off\" spellcheck=\"false\"> <br>Researchers like to find a <span class=\"qnum\">37</span><input class=\"gap\" data-q=\"37\" aria-label=\"Câu 37\" autocomplete=\"off\" spellcheck=\"false\">  with language barrier/ language learning difficulty<br>Children are likely to have some problems with   <span class=\"qnum\">38</span><input class=\"gap\" data-q=\"38\" aria-label=\"Câu 38\" autocomplete=\"off\" spellcheck=\"false\"> <br>With this approach, children no longer needed   <span class=\"qnum\">39</span><input class=\"gap\" data-q=\"39\" aria-label=\"Câu 39\" autocomplete=\"off\" spellcheck=\"false\">  training again<br>The mathematics disorder is popular with   <span class=\"qnum\">40</span><input class=\"gap\" data-q=\"40\" aria-label=\"Câu 40\" autocomplete=\"off\" spellcheck=\"false\">   and families of children</p>"}], "passages": [], "singles": [{"n": 16, "prompt": "bookshop aims to", "options": ["sell as many books as possible", "create an energetic environment", "attract people to remain in the shop"]}, {"n": 17, "prompt": "children’s books are located", "options": ["ground floor", "highest level", "midway up"]}, {"n": 18, "prompt": "parents to relax", "options": ["train floor-staff to take care children", "free nursery", "professional child care"]}, {"n": 19, "prompt": "regular book reading", "options": ["to sell more books", "author gathering", "bring more money by charing"]}, {"n": 20, "prompt": "poetry workshop", "options": ["encourage their works to be published", "to become professional poet", "to read them in public"]}, {"n": 21, "prompt": "Ron suggests that in his presentation he should have", "options": ["given credit to the originators of the JIT idea.", "discussed why the Japanese adopted the JIT idea.", "explained how supermarkets used the JIT idea."]}, {"n": 22, "prompt": "The tutor says that in his presentation Ron omitted", "options": ["a description of classic business theory.", "an introductory definition of JIT.", "a statement of the aims of JIT."]}, {"n": 23, "prompt": "Ron says that he found his information on standardising parts from", "options": ["a website.", "journal articles", "a textbook."]}, {"n": 24, "prompt": "The tutor suggests that in the service sector, JIT is", "options": ["difficult to apply because of the absence of countable things.", "regarded by most members of staff as unfashionable", "unlikely to be accepted by important clients."]}], "pairs": [], "answers": {"1": ["30 March 1988", "30th March 1988", "March 30 1988", "March 30th 1988", "30/3/1988"], "2": ["0903775115"], "3": ["northern"], "4": ["train"], "5": ["hotel"], "6": ["farm"], "7": ["pass"], "8": ["booklet"], "9": ["insurance"], "10": ["internet cafe", "internet café"], "11": ["C"], "12": ["F"], "13": ["D"], "14": ["A"], "15": ["H"], "16": ["C"], "17": ["B"], "18": ["C"], "19": ["A"], "20": ["C"], "21": ["A"], "22": ["B"], "23": ["C"], "24": ["A"], "25": ["B"], "26": ["H"], "27": ["D"], "28": ["G"], "29": ["E"], "30": ["F"], "31": ["traditional"], "32": ["time"], "33": ["money"], "34": ["confidence"], "35": ["guesses"], "36": ["walking"], "37": ["link"], "38": ["concentration"], "39": ["additional"], "40": ["teachers"]}, "explanations": {"1": "<p><b>Câu 1: 30 March 1988</b></p><p>• Vị trí:<br>– Agent hỏi: “Date of birth?”<br>– Sarah trả lời: “March the 30th… 1988.”<br>• Hint: nghe ngày + năm, sửa lại ngay sau khi nói nhầm.<br>• Paraphrase:<br>– March the 30th = 30 March<br>• Lưu ý IELTS: chấp nhận nhiều cách viết, nhưng nên đủ ngày + năm.</p>", "2": "<p><b>Câu 2: 0903775115</b></p><p>• Vị trí: “a contact telephone number”<br>• Sarah nói: “my mobile number… 0903 775 115”<br>• Hint: nghe từng cụm số → nối lại, không có khoảng trắng.<br>• Paraphrase:<br>– mobile number = contact tel. no.</p>", "3": "<p><b>Câu 3: northern</b></p><p>• Vị trí: “I’d like to go to Northern Europe.”<br>• Form: “wants to travel in … Europe”<br>• Paraphrase:<br>– Northern Europe = Europe (phía Bắc)<br>• Lưu ý: chỉ cần 1 từ, không viết “Europe”.</p>", "4": "<p><b>Câu 4: train</b></p><p>• Vị trí: “I’d like to go by train…”<br>• Paraphrase:<br>– go by train = travel by train<br>• Hint: so sánh với “We always went by plane” → nhấn mạnh lựa chọn mới.</p>", "5": "<p><b>Câu 5: hotel</b></p><p>• Vị trí: “I thought about hotel work…”<br>• Form: “interested in working in a …”<br>• Paraphrase:<br>– hotel work = working in a hotel<br>• Lưu ý: không thêm “work”.</p>", "6": "<p><b>Câu 6: farm</b></p><p>• Vị trí: “lots of students like to work on a farm”<br>• Form: “consider an alternative e.g. … work”<br>• Paraphrase:<br>– work on a farm = farm work<br>• Hint: “alternative” → phương án dự phòng.</p>", "7": "<p><b>Câu 7: pass</b></p><p>• Vị trí: “the best option would be to have a European pass”<br>• Paraphrase:<br>– European pass = rail pass<br>• Lưu ý: chỉ điền pass, không thêm “European”.</p>", "8": "<p><b>Câu 8: booklet</b></p><p>• Vị trí: “I’ll give you a booklet now.”<br>• Form: “given a … with accommodation details”<br>• Paraphrase:<br>– booklet = brochure (nhưng bài dùng booklet).</p>", "9": "<p><b>Câu 9: insurance</b></p><p>• Vị trí: “you need to have insurance… We can arrange that for you”<br>• Paraphrase:<br>– take out insurance = mua bảo hiểm<br>• Hint: “from the Agency” → mua qua bên này.</p>", "10": "<p><b>Câu 10: internet cafe</b></p><p>• Vị trí: “It’s much more sensible to rely on an internet cafe.”<br>• Paraphrase:<br>– keep in touch = contact people<br>• Lưu ý: viết đúng 2 từ, không gạch nối.</p>", "11": "<p><b>Câu 11: seating area → C</b></p><p>• Location:<br>– “Right in the centre of this floor… is our main seating area”<br>• Hint:<br>– “right in the centre” = ở giữa bản đồ<br>• Paraphrase:<br>– seating area = nơi ngồi đọc sách<br>→ Trên bản đồ, vị trí trung tâm = C</p>", "12": "<p><b>Câu 12: cushions → F</b></p><p>• Location:<br>– “to your immediate left… piles of coloured cushions in front of the window”<br>• Hint:<br>– immediate left + in front of the window<br>• Paraphrase:<br>– cushions = gối ngồi<br>→ Ký hiệu tương ứng trên bản đồ = F</p>", "13": "<p><b>Câu 13: computer bench → D</b></p><p>• Location:<br>– “On your right, between the two larger bookshelves, you’ll see the computer bench”<br>• Hint:<br>– on your right<br>– between two shelves<br>• Paraphrase:<br>– computer bench = bàn tra cứu máy tính<br>→ Vị trí đó trên bản đồ = D</p>", "14": "<p><b>Câu 14: café bar → A</b></p><p>• Location:<br>– “at the far end, just in front of the lift… a small café bar”<br>• Hint:<br>– far end + near lift<br>• Paraphrase:<br>– café bar = quầy cà phê<br>→ Trên bản đồ là A</p>", "15": "<p><b>Câu 15: newspapers → H</b></p><p>• Location:<br>– “there’s a stand where we keep a selection of local and national newspapers”<br>• Hint:<br>– stand = quầy/giá trưng bày<br>• Paraphrase:<br>– newspapers = báo<br>→ Ký hiệu tương ứng = H</p>", "16": "<p><b>Câu 16: bookshop aims to → C</b></p><p>• Location:<br>– “our purpose is to draw people in… makes them want to stay and read”<br>• Hint:<br>– stay and read ≠ mua ngay<br>• Paraphrase:<br>– attract people to remain = khiến khách ở lại lâu<br>→ Đáp án đúng: C</p>", "17": "<p><b>Câu 17: children’s books are located → B</b></p><p>• Location:<br>– “we decided to put them on the very top level”<br>• Paraphrase:<br>– very top level = highest level<br>→ Đáp án: B</p>", "18": "<p><b>Câu 18: parents to relax → C</b></p><p>• Location:<br>– “we decided to employ qualified nursery staff”<br>• Hint:<br>– parents’ complete peace of mind<br>• Paraphrase:<br>– professional child care = trông trẻ chuyên nghiệp<br>→ Đáp án: C</p>", "19": "<p><b>Câu 19: regular book reading → A</b></p><p>• Location:<br>– “we hope that some of them will want to purchase the book”<br>• Hint:<br>– không thu phí tham dự → mục đích gián tiếp bán sách<br>• Paraphrase:<br>– purchase = buy<br>→ Đáp án: A</p>", "20": "<p><b>Câu 20: poetry workshop → C</b></p><p>• Location:<br>– “the participants read their poems aloud”<br>• Hint:<br>– read aloud ≠ xuất bản ≠ trở thành nhà thơ chuyên nghiệp<br>• Paraphrase:<br>– read in public = đọc trước mọi người<br>→ Đáp án: C</p>", "21": "<p><b>Câu 21</b></p><p>Đáp án: <i>A – given credit to the originators of the JIT idea</i></p><p>Giải thích:</p><p>Vị trí nghe: Ngay đầu phần nhận xét, Ron nói “one thing I should have made clearer… the Americans actually pioneered the idea”.</p><p>Ý chính: Ron thừa nhận lẽ ra nên nói rõ nguồn gốc ban đầu của JIT (do người Mỹ khởi xướng, không phải Nhật).</p><p>Hint: “should have made clearer”, “pioneered the idea”</p><p>Paraphrase:</p><p>originators = người khởi xướng</p><p>pioneered = đi tiên phong</p>", "22": "<p><b>Câu 22</b></p><p>Đáp án: <i>B – an introductory definition of JIT</i></p><p>Giải thích:</p><p>Vị trí nghe: Tutor nói: “you should have stopped and clearly defined just-in-time”.</p><p>Ý chính: Ron không đưa ra định nghĩa rõ ràng ban đầu về JIT cho người nghe.</p><p>Hint: “clearly defined”, “you never told us that JIT simply means…”</p><p>Paraphrase:</p><p>introductory definition = định nghĩa mở đầu</p><p>clearly defined = định nghĩa rõ ràng</p>", "23": "<p><b>Câu 23</b></p><p>Đáp án:<i> C – a textbook</i></p><p>Giải thích:</p><p>Vị trí nghe: Ron nói: “in the end, I got my data from a textbook called Learning from Toyota”.</p><p>Ý chính: Nguồn thông tin chính Ron dùng là sách giáo trình.</p><p>Loại trừ:</p><p>Website → “too technical”</p><p>Journal articles → “didn’t seem very useful”</p><p>Paraphrase:</p><p>textbook = sách giáo trình</p>", "24": "<p><b>Câu 24</b></p><p>Đáp án: <i>A – difficult to apply because of the absence of countable things</i></p><p>Giải thích:</p><p>Vị trí nghe: Tutor nói về service industries: “customers are paying for something they can’t actually see or count”.</p><p>Ý chính: JIT khó áp dụng trong dịch vụ vì không có sản phẩm hữu hình để đếm/định lượng.</p><p>Hint: “can’t actually see or count”, “quantified”</p><p>Paraphrase:</p><p>absence of countable things = không có thứ có thể đếm được</p><p>quantified = định lượng</p>", "25": "<p><b>Câu 25 – speed of delivery</b></p><p>Đáp án: <i>B – too irregular</i></p><p>Giải thích:</p><p>Vị trí nghe: Ron nói: “sometimes seemed to talk fast and sometimes slow”.</p><p>Ý chính: Tốc độ nói không ổn định.</p><p>Paraphrase:</p><p>too irregular = lúc nhanh lúc chậm, không đều</p>", "26": "<p><b>Câu 26 – purpose</b></p><p>Đáp án: <i>H – too vague</i></p><p>Giải thích:</p><p>Vị trí nghe: Tutor: “your purpose wasn’t very specific”, “not so general”.</p><p>Ý chính: Mục đích bài nói quá chung chung, không rõ ràng.</p><p>Paraphrase:</p><p>not very specific = mơ hồ</p><p>too vague = không cụ thể</p>", "27": "<p><b>Câu 27 – transitions</b></p><p>Đáp án: <i>D – too sudden</i></p><p>Giải thích:</p><p>Vị trí nghe: Tutor: “You went too quickly from one to the next”, “too abrupt”.</p><p>Ý chính: Chuyển ý đột ngột, không liên kết mượt.</p><p>Paraphrase:</p><p>too abrupt = quá đột ngột</p><p>too sudden = quá bất ngờ</p>", "28": "<p><b>Câu 28 – visuals</b></p><p>Đáp án: <i>G – too loosely related</i></p><p>Giải thích:</p><p>Vị trí nghe: Tutor: “they didn’t have much to do with what you were talking about”.</p><p>Ý chính: Slide đẹp nhưng liên quan lỏng lẻo đến nội dung nói.</p><p>Paraphrase:</p><p>didn’t have much to do with = liên quan không chặt</p><p>too loosely related = liên kết lỏng</p>", "29": "<p><b>Câu 29 – vocabulary</b></p><p>Đáp án: <i>E – too technical</i></p><p>Giải thích:</p><p>Vị trí nghe: Tutor: “they just didn’t understand some of the vocabulary”, “simplify”.</p><p>Ý chính: Từ vựng quá học thuật/chuyên môn, không phù hợp người nghe phổ thông.</p><p>Paraphrase:</p><p>too technical = quá chuyên ngành</p><p>laymen = người không chuyên</p>", "30": "<p><b>Câu 30 – body language</b></p><p>Đáp án: <i>F – too unenthusiastic</i></p><p>Giải thích:</p><p>Vị trí nghe: Tutor: “You didn’t use gestures”, “didn’t make you seem very interested”.</p><p>Ý chính: Ngôn ngữ cơ thể thiếu năng lượng, thiếu nhiệt tình.</p><p>Paraphrase:</p><p>not animated = không sinh động</p><p>too unenthusiastic = thiếu hứng thú</p>", "31": "<p><b>Câu 31</b></p><p>Đáp án: <i>traditional</i></p><p>Vị trí nghe: Đầu bài nói.</p><p>Giải thích: Hầu hết trường học đang dùng phương pháp dạy toán truyền thống, nhưng không hiệu quả với trẻ mắc Dyscalculia.</p><p>Hint: “most schools use the traditional method of teaching mathematics”</p><p>Paraphrase:</p><p>traditional method = phương pháp truyền thống</p>", "32": "<p><b>Câu 32</b></p><p>Đáp án: <i>time</i></p><p>Vị trí nghe: Đoạn nói về khó khăn trong nhận thức.</p><p>Giải thích: Trẻ gặp khó khăn với khái niệm thời gian và trình tự (sequence).</p><p>Hint: “concept of time and sequence”</p><p>Paraphrase:</p><p>passage of time = dòng chảy thời gian</p><p>order = trình tự</p>", "33": "<p><b>Câu 33</b></p><p>Đáp án: <i>money</i></p><p>Vị trí nghe: Khi nói về ví dụ thực tế trong lớp học.</p><p>Giải thích: Giáo viên cho luyện tập qua tình huống xử lý tiền vì đây là khó khăn phổ biến.</p><p>Hint: “activities that involve dealing with money”</p><p>Paraphrase:</p><p>dealing with = xử lý</p>", "34": "<p><b>Câu 34</b></p><p>Đáp án: <i>confidence</i></p><p>Vị trí nghe: Đoạn nói về mục tiêu của việc luyện tập thêm.</p><p>Giải thích: Luyện thêm phép tính để tăng sự tự tin khi làm toán.</p><p>Hint: “To boost their confidence”</p><p>Paraphrase:</p><p>boost = tăng cường</p><p>self-assurance = sự tự tin</p>", "35": "<p><b>Câu 35</b></p><p>Đáp án: <i>guesses</i></p><p>Vị trí nghe: Khi nói về chiến lược giải quyết vấn đề.</p><p>Giải thích: Giáo viên khuyến khích trẻ đoán có cơ sở khi gặp bài toán khó.</p><p>Hint: “encourage children to make educated guesses”</p><p>Paraphrase:</p><p>educated guesses = đoán có căn cứ</p>", "36": "<p><b>Câu 36</b></p><p>Đáp án: <i>walking</i></p><p>Vị trí nghe: Đoạn liệt kê các bài tập hỗ trợ.</p><p>Giải thích: Ngoài thở và thư giãn, còn có đi bộ để giảm căng thẳng, tăng tập trung.</p><p>Hint: “breathing techniques, relaxation exercises, and even walking breaks”</p><p>Paraphrase:</p><p>walking breaks = nghỉ đi bộ</p>", "37": "<p><b>Câu 37</b></p><p>Đáp án: <i>link</i></p><p>Vị trí nghe: Đoạn nói về nghiên cứu.</p><p>Giải thích: Các nhà nghiên cứu tìm mối liên hệ giữa Dyscalculia và khó khăn ngôn ngữ.</p><p>Hint: “finding a potential link between Dyscalculia and language learning difficulties”</p><p>Paraphrase:</p><p>connection = mối liên hệ</p>", "38": "<p><b>Câu 38</b></p><p>Đáp án: <i>concentration</i></p><p>Vị trí nghe: Khi nói về khó khăn thường gặp khác.</p><p>Giải thích: Trẻ thường gặp vấn đề về khả năng tập trung.</p><p>Hint: “struggle with concentration and maintaining focus”</p><p>Paraphrase:</p><p>maintaining focus = duy trì sự tập trung</p>", "39": "<p><b>Câu 39</b></p><p>Đáp án: <i>additional</i></p><p>Vị trí nghe: Gần cuối bài, nói về kết quả của cách tiếp cận toàn diện.</p><p>Giải thích: Với cách dạy này, trẻ không cần thêm các chương trình huấn luyện riêng biệt.</p><p>Hint: “may no longer require additional treatment or training”</p><p>Paraphrase:</p><p>additional = bổ sung, thêm</p>", "40": "<p><b>Câu 40</b></p><p>Đáp án: <i>teachers</i></p><p>Vị trí nghe: Câu kết của bài.</p><p>Giải thích: Rối loạn này ảnh hưởng đến giáo viên và gia đình của trẻ.</p><p>Hint: “affects not only the children, but also their families and teachers”</p><p>Paraphrase:</p><p>affects = ảnh hưởng</p>"}, "transcriptSegments": {"1": [{"id": "s1-t1", "text": "You will hear a number of different recordings, and you will have to answer questions on what you hear. There will be time for you to read the instructions and questions, and you will have a chance to check your work. All the recordings will be played once only.", "html": "<p>You will hear a number of different recordings, and you will have to answer questions on what you hear. There will be time for you to read the instructions and questions, and you will have a chance to check your work. All the recordings will be played once only.</p>", "start": null}, {"id": "s1-t2", "text": "The test is in four parts. Write all your answers in the listening question booklet. At the end of the test, you will be given 10 minutes to transfer your answers to an answer sheet.", "html": "<p>The test is in four parts. Write all your answers in the listening question booklet. At the end of the test, you will be given 10 minutes to transfer your answers to an answer sheet.</p>", "start": null}, {"id": "s1-t3", "text": "Now turn to part 1 on page 2 of your question booklet. Part 1 You will hear a conversation between a travel agent and a student who is planning a trip abroad. First, you have some time to look at questions 1 to 6.", "html": "<p>Now turn to part 1 on page 2 of your question booklet. Part 1 You will hear a conversation between a travel agent and a student who is planning a trip abroad. First, you have some time to look at questions 1 to 6.</p>", "start": null}, {"id": "s1-t4", "text": "Now listen carefully and answer questions 1 to 6. Hello, how can I help you? I'm taking a year off and I'm hoping to travel abroad and to find work as well for part of the time.", "html": "<p>Now listen carefully and answer questions 1 to 6. Hello, how can I help you? I&#x27;m taking a year off and I&#x27;m hoping to travel abroad and to find work as well for part of the time.</p>", "start": null}, {"id": "s1-t5", "text": "I know you specialise in student travel and work placement, so... That's right, we can help you arrange your travel and set up a job for you. But first of all, I need some personal details, and then we'll match your details against our database to see what's available work-wise.", "html": "<p>I know you specialise in student travel and work placement, so... That&#x27;s right, we can help you arrange your travel and set up a job for you. But first of all, I need some personal details, and then we&#x27;ll match your details against our database to see what&#x27;s available work-wise.</p>", "start": null}, {"id": "s1-t6", "text": "Great. OK, your full name? Sarah Brown.", "html": "<p>Great. OK, your full name? Sarah Brown.</p>", "start": null}, {"id": "s1-t7", "text": "Date of birth? Q1 March the 30th. Oh, I'm the 31st!", "html": "<p>Date of birth? Q1 <u>March the 30th</u>. Oh, I&#x27;m the 31st!</p>", "start": null}, {"id": "s1-t8", "text": "1988. And your address? 21 Waverley Road, Radstone RD46WV.", "html": "<p><u>1988</u>. And your address? 21 Waverley Road, Radstone RD46WV.</p>", "start": null}, {"id": "s1-t9", "text": "And a contact telephone number, please. I can give you my mobile number. Q2 0903 775 115.", "html": "<p>And a contact telephone number, please. I can give you my mobile number. Q2 <u>0903 775 115</u>.</p>", "start": null}, {"id": "s1-t10", "text": "Fine. Now, tell me where you plan to travel to and I'll see how I can help. Well, I'd like to go to Q3 Northern Europe.", "html": "<p>Fine. Now, tell me where you plan to travel to and I&#x27;ll see how I can help. Well, I&#x27;d like to go to Q3 <u>Northern</u> Europe.</p>", "start": null}, {"id": "s1-t11", "text": "Have you been there before? No, I know Southern Europe quite well as I've been there with my family. We always went by plane, but now I can choose.", "html": "<p>Have you been there before? No, I know <u>Southern Europe</u> quite well as I&#x27;ve been there with my family. We always went by plane, but now I can choose.</p>", "start": null}, {"id": "s1-t12", "text": "I'd like to go by Q4 train so I can stop off whenever I want. OK. Now, just as important, what sort of work have you got in mind?", "html": "<p>I&#x27;d like to go by Q4 <u>train</u> so I can stop off whenever I want. OK. Now, just as important, what sort of work have you got in mind?</p>", "start": null}, {"id": "s1-t13", "text": "Well, I thought about Q5 hotel work because then I might get accommodation with the job and I'd like to work for about half the year. That sort of work is usually quite competitive. Perhaps you should consider an alternative just in case.", "html": "<p>Well, I thought about Q5 <u>hotel</u> work because then I might get accommodation with the job and I&#x27;d like to work for about half the year. That sort of work is usually quite competitive. Perhaps you should consider an alternative just in case.</p>", "start": null}, {"id": "s1-t14", "text": "Such as? Well, lots of students like to work on a Q6 farm and we have lots of requests from people looking for student workers for a few weeks at a time throughout the year. You can generally earn quite good money if you're willing to work fairly long hours.", "html": "<p>Such as? Well, lots of students like to work on a Q6 <u>farm</u> and we have lots of requests from people looking for student workers for a few weeks at a time throughout the year. You can generally earn quite good money if you&#x27;re willing to work fairly long hours.</p>", "start": null}, {"id": "s1-t15", "text": "Before you hear the rest of the conversation, you have some time to look at questions 7 to 10. Now listen and answer questions 7 to 10. Now, travel.", "html": "<p>Before you hear the rest of the conversation, you have some time to look at questions 7 to 10. Now listen and answer questions 7 to 10. Now, travel.</p>", "start": null}, {"id": "s1-t16", "text": "Buying single tickets would be expensive so the best option would be to have a Q7 European pass which would give you unlimited rail travel at off-peak times. To start off with, we could issue one for up to three months to cover the countries you're intending to visit. Sounds good.", "html": "<p>Buying single tickets would be expensive so the best option would be to have a Q7 <u>European</u> pass which would give you unlimited rail travel at off-peak times. To start off with, we could issue one for up to three months to cover the countries you&#x27;re intending to visit. Sounds good.</p>", "start": null}, {"id": "s1-t17", "text": "Do you have any information about youth hostels which I could use to plan my route? Yes, I'll give you a Q8 booklet now. But it's down to you to book your accommodation.", "html": "<p>Do you have any information about youth hostels which I could use to plan my route? Yes, I&#x27;ll give you a Q8 <u>booklet</u> now. But it&#x27;s down to you to book your accommodation.</p>", "start": null}, {"id": "s1-t18", "text": "At certain times of the year, especially during public holiday periods, such places fill up fast. And remember, if we're going to arrange work for you in the countryside, you won't be able to go out easily in the evenings. Although you'd probably be too tired anyway.", "html": "<p>At certain times of the year, especially during public holiday periods, such places fill up fast. And remember, if we&#x27;re going to arrange work for you in the countryside, you won&#x27;t be able to go out easily in the evenings. Although you&#x27;d probably be too tired anyway.</p>", "start": null}, {"id": "s1-t19", "text": "I won't mind that. And you're going to be travelling alone? Yes.", "html": "<p>I won&#x27;t mind that. And you&#x27;re going to be travelling alone? Yes.</p>", "start": null}, {"id": "s1-t20", "text": "Well, before I make any arrangements for you, you need to have Q9 insurance for your entire trip. We can arrange that for you if you like. What does it cover?", "html": "<p>Well, before I make any arrangements for you, you need to have Q9 <u>insurance</u> for your entire trip. We can arrange that for you if you like. What does it cover?</p>", "start": null}, {"id": "s1-t21", "text": "Any valuable items, jewellery for example, your money, your mobile, your health, and if you needed to get back home quickly, you'd be covered so you could buy a plane ticket. Right, I'll do that. I thought I'd take my laptop so I can email and keep in touch with people at home.", "html": "<p>Any valuable items, jewellery for example, your money, your mobile, your health, and if you needed to get back home quickly, you&#x27;d be covered so you could buy a plane ticket. Right, I&#x27;ll do that. I thought I&#x27;d take my laptop so I can email and keep in touch with people at home.</p>", "start": null}, {"id": "s1-t22", "text": "Not a good idea to lug your computer around with you. It's much more sensible to rely on an Q10 internet cafe. That's what we tell people to do.", "html": "<p>Not a good idea to lug your computer around with you. It&#x27;s much more sensible to rely on an Q10 <u>internet cafe</u>. That&#x27;s what we tell people to do.</p>", "start": null}, {"id": "s1-t23", "text": "Oh, OK. Right, so I've entered all your details, let's see what the database comes up with. That is the end of part one. You now have one minute to check your answers to part one.", "html": "<p>Oh, OK. Right, so I&#x27;ve entered all your details, let&#x27;s see what the database comes up with. That is the end of part one. You now have one minute to check your answers to part one.</p>", "start": null}], "2": [{"id": "s2-t1", "text": "Part two. You will hear the manager of a bookshop called Bibliostack talking to a group of young people about the way the bookshop is organised.", "html": "<p>Part two. You will hear the manager of a bookshop called Bibliostack talking to a group of young people about the way the bookshop is organised.</p>", "start": null}, {"id": "s2-t2", "text": "First, you have some time to look at questions 11 to 15. Now listen carefully and answer questions 11 to 15. Good morning, everyone, and a big welcome to Bibliostack.", "html": "<p>First, you have some time to look at questions 11 to 15. Now listen carefully and answer questions 11 to 15. Good morning, everyone, and a big welcome to Bibliostack.</p>", "start": null}, {"id": "s2-t3", "text": "Firstly, I'll explain the plan of the store to you. The building is on seven floors and is circular, as you can see, and we're here on the ground floor in its entrance hall. Q11 Right in the centre of this floor, but behind the bookshelf so you can't see it very well from here, is our main seating area, where people are encouraged to sit and read for as long as they like.", "html": "<p>Firstly, I&#x27;ll explain the plan of the store to you. The building is on seven floors and is circular, as you can see, and we&#x27;re here on the ground floor in its entrance hall. Q11 Right in the centre of this floor, but behind the bookshelf so you can&#x27;t see it very well from here, is our main <i>seating area</i>, where people are encouraged to sit and read for as long as they like.</p>", "start": null}, {"id": "s2-t4", "text": "But they're under no pressure to buy what they're reading. That's not how we operate. And if you look Q12 to your immediate left, past the first double row of shelves, you'll see piles of coloured cushions in front of the window there.", "html": "<p>But they&#x27;re under no pressure to buy what they&#x27;re reading. That&#x27;s not how we operate. And if you look Q12 to your immediate left, past the first double row of shelves, you&#x27;ll see piles of coloured <i>cushions</i> in front of the window there.</p>", "start": null}, {"id": "s2-t5", "text": "We provide those so that people can sit wherever they want. Lots of people like to sit close to the bookshelves, and if they want to sit on the floor there, we want them to be as comfortable as possible. Q13 On your right, between the two larger bookshelves, you'll see the computer bench, where our visitors can search through our entire catalogue.", "html": "<p>We provide those so that people can sit wherever they want. Lots of people like to sit close to the bookshelves, and if they want to sit on the floor there, we want them to be as comfortable as possible. Q13 On your right, between the two larger bookshelves, you&#x27;ll see the <i>computer bench</i>, where our visitors can search through our entire catalogue.</p>", "start": null}, {"id": "s2-t6", "text": "We pride ourselves in being the largest bookshop in the country, so our sales assistants can't possibly know all the available titles. Although the room in front of you is dominated by the bookshelves, Q14 at the far end, just in front of the lift, you'll see that we provide a small cafe bar here too. And just to your right, there's a door to the cloakroom, where people can leave their coats.", "html": "<p>We pride ourselves in being the largest bookshop in the country, so our sales assistants can&#x27;t possibly know all the available titles. Although the room in front of you is dominated by the bookshelves, Q14 at the far end, just in front of the lift, you&#x27;ll see that we provide a small <i>cafe bar</i> here too. And just to your right, there&#x27;s a door to the cloakroom, where people can leave their coats.</p>", "start": null}, {"id": "s2-t7", "text": "Then after that, Q15 there's a stand where we keep a selection of local and national newspapers. Customers are welcome to browse through them, and we also have some for sale. We really want people to feel as though they're browsing through books in the comfort of their own home.", "html": "<p>Then after that, Q15 there&#x27;s a stand where we keep a selection of local and national <i>newspapers</i>. Customers are welcome to browse through them, and we also have some for sale. We really want people to feel as though they&#x27;re browsing through books in the comfort of their own home.</p>", "start": null}, {"id": "s2-t8", "text": "Before you hear the rest of the talk, you have some time to look at questions 16 to 20. Now listen and answer questions 16 to 20. Right, now I suggest we walk slowly up through the building, and I'll give you more information as we go.", "html": "<p>Before you hear the rest of the talk, you have some time to look at questions 16 to 20. Now listen and answer questions 16 to 20. Right, now I suggest we walk slowly up through the building, and I&#x27;ll give you more information as we go.</p>", "start": null}, {"id": "s2-t9", "text": "We're open 12 hours a day. We don't mind if people spend the whole day here, but leave without buying anything. Of course, we hope they'll buy something, but Q16 our purpose is to draw people in, to provide the kind of environment which makes them want to stay and read.", "html": "<p>We&#x27;re open 12 hours a day. We don&#x27;t mind if people spend the whole day here, but leave without buying anything. Of course, we hope they&#x27;ll buy something, but Q16 <i>our purpose is</i> <u>to draw people in</u>, to provide the kind of environment which <u>makes them want to stay and read</u>.</p>", "start": null}, {"id": "s2-t10", "text": "Look at how busy each floor is, but how quiet. You may be wondering whether there are any children in the building. We debated about locating children's books on the ground floor, or halfway up the building, like the third or fourth floor, but in the end, Q17 we decided to put them on the very top level, and I can assure you it's not the least bit quiet up there.", "html": "<p>Look at how busy each floor is, but how quiet. You may be wondering whether there are any children in the building. We debated about <i>locating children&#x27;s books</i> on the ground floor, or halfway up the building, like the third or fourth floor, but in the end, Q17 we decided to put them <u>on the very top level</u>, and I can assure you it&#x27;s not the least bit quiet up there.</p>", "start": null}, {"id": "s2-t11", "text": "Of course, many parents would prefer to spend time on other floors, and so we provide a supervised area for children under two in the basement, so parents can wander around the shop for a few hours and not worry. But they do have to pay for this service, because although we thought about using some of our own assistants, Q18 we decided to employ qualified nursery staff for parents' complete peace of mind. Now, we're just passing the fiction section, and you've probably noticed a small crowd of people beginning to gather.", "html": "<p>Of course, many parents would prefer to spend time on other floors, and so we provide a supervised area for children under two in the basement, so parents can wander around the shop for a few hours and not worry. But they do have to pay for this service, because although we thought about using some of our own assistants, Q18 we decided to employ <u>qualified nursery staff</u> for <i>parents&#x27; complete peace of mind</i>. Now, we&#x27;re just passing the fiction section, and you&#x27;ve probably noticed a small crowd of people beginning to gather.</p>", "start": null}, {"id": "s2-t12", "text": "That's because a well-known author is going to read from her latest novel. We try to hold events like this at least once or twice a week, and as you can imagine, they're very popular. We don't make a charge for people to attend, but Q19 we obviously hope that some of them will want to purchase the book after listening to part of it being read aloud.", "html": "<p>That&#x27;s because a well-known author is going to read from her latest novel. We try to hold events like this at least once or twice a week, and as you can imagine, they&#x27;re very popular. We don&#x27;t make a charge for people to attend, but Q19 we obviously hope that some of them will want to <u>purchase the book</u> after listening to part of it being read aloud.</p>", "start": null}, {"id": "s2-t13", "text": "Other events which are proving to be very popular are our workshops. Last week, we held a poetry workshop, and people came along with poems that they'd written. One of the country's best-known poets ran the workshop, and Q20 the participants read their poems aloud to him.", "html": "<p>Other events which are proving to be very popular are our workshops. Last week, we held a <i>poetry workshop</i>, and people came along with poems that they&#x27;d written. One of the country&#x27;s best-known poets ran the workshop, and Q20 the participants <u>read their poems aloud</u> to him.</p>", "start": null}, {"id": "s2-t14", "text": "He was kind and encouraging, and many people felt inspired by his advice. It's extremely difficult to earn your living as a professional poet, and even published poets have other jobs. Now, we're going to take a look at our section on audiobooks.", "html": "<p>He was kind and encouraging, and many people felt inspired by his advice. It&#x27;s extremely difficult to earn your living as a professional poet, and even published poets have other jobs. Now, we&#x27;re going to take a look at our section on audiobooks.</p>", "start": null}, {"id": "s2-t15", "text": "That is the end of part two. You now have 30 seconds to check your answers to part two.", "html": "<p>That is the end of part two. You now have 30 seconds to check your answers to part two.</p>", "start": null}], "3": [{"id": "s3-t1", "text": "Part three. You will hear a business student called Ron getting feedback from his tutor on his presentation. First, you have some time to look at questions 21 to 24. Now listen carefully and answer questions 21 to 24.", "html": "<p>Part three. You will hear a business student called Ron getting feedback from his tutor on his presentation. First, you have some time to look at questions 21 to 24. Now listen carefully and answer questions 21 to 24.</p>", "start": null}, {"id": "s3-t2", "text": "Thanks, Ron, for coming to my office to discuss the presentation you gave yesterday to the business management seminar. We'll go over what you did with the aim of helping you improve your next presentation. Sounds good.", "html": "<p>Thanks, Ron, for coming to my office to discuss the presentation you gave yesterday to the business management seminar. We&#x27;ll go over what you did with the aim of helping you improve your next presentation. Sounds good.</p>", "start": null}, {"id": "s3-t3", "text": "Now, the topic was the just-in-time, or JIT, supply system used by a lot of manufacturers, first in Japan and then in the West, I think. Yes, but actually Q21 one thing I should have made clearer and talked about was the fact that the Americans actually pioneered the idea of just-in-time, though it wasn't called that. Henry Ford and his cars, in fact, at the turn of the 20th century.", "html": "<p>Now, the topic was the just-in-time, or JIT, supply system used by a lot of manufacturers, first in Japan and then in the West, I think. Yes, but actually Q21 one thing I should have <u>made clearer and talked about was the fact that the Americans actually pioneered the idea</u> of just-in-time, though it wasn&#x27;t called that. Henry Ford and his cars, in fact, at the turn of the 20th century.</p>", "start": null}, {"id": "s3-t4", "text": "And later, a big US supermarket chain used it, and this was where Toyota in Japan got the idea for its car making. Yes, that would have been a good addition. Now, before we go any further, I think I would suggest that Q22 you should have stopped and clearly defined just-in-time for your seminar colleagues.", "html": "<p>And later, a big US supermarket chain used it, and this was where Toyota in Japan got the idea for its car making. Yes, that would have been a good addition. Now, before we go any further, I think I would suggest that Q22 you should have stopped and <u>clearly defined</u> just-in-time for your seminar colleagues.</p>", "start": null}, {"id": "s3-t5", "text": "You said its aim was to reduce waste, and you mentioned that classic business theory assumes that stock, or inventory of parts, are counted as assets, but just-in-time sees them as unnecessary waste. But you never told us that JIT simply means waiting until the last moment to order new supplies as you need them. Yes, you're right.", "html": "<p>You said its aim was to reduce waste, and you mentioned that classic business theory assumes that stock, or inventory of parts, are counted as assets, but just-in-time sees them as unnecessary waste. But you never told us that JIT simply means waiting until the last moment to order new supplies as you need them. Yes, you&#x27;re right.</p>", "start": null}, {"id": "s3-t6", "text": "I should have done that. Now, you talked a bit about standardising parts as a way of streamlining JIT. Where did you get your data from?", "html": "<p>I should have done that. Now, you talked a bit about standardising parts as a way of streamlining JIT. Where did you get your data from?</p>", "start": null}, {"id": "s3-t7", "text": "Well, I tried an internet website on the subject which is called The Lean Clearinghouse, but it was too technical for me. So, Q23 in the end, I got my data from a textbook called Learning from Toyota. I found some journal articles too, but they didn't seem very useful.", "html": "<p>Well, I tried an internet website on the subject which is called The Lean Clearinghouse, but it was too technical for me. So, Q23 in the end, I got my data from <u>a textbook</u> called Learning from Toyota. I found some journal articles too, but they didn&#x27;t seem very useful.</p>", "start": null}, {"id": "s3-t8", "text": "Yes, well, there is a US government report on it I've seen. I'll get a copy for you. Great.", "html": "<p>Yes, well, there is a US government report on it I&#x27;ve seen. I&#x27;ll get a copy for you. Great.</p>", "start": null}, {"id": "s3-t9", "text": "I look forward to reading through it. And while you're at it, you might want to find out about cases where JIT might not be suitable. And that's in service industries like tourism or healthcare, where Q24 customers are paying for something that they can't actually see or count.", "html": "<p>I look forward to reading through it. And while you&#x27;re at it, you might want to find out about cases where JIT might not be suitable. And that&#x27;s in <i>service industries</i> like tourism or healthcare, where Q24 customers are paying for something that they <u>can&#x27;t actually see or count</u>.</p>", "start": null}, {"id": "s3-t10", "text": "Although JIT is fashionable today, some people would say it hasn't proved so successful in the service sector as it has with the manufacturing of goods that can be quantified. That would be interesting. I'll see what I can find out.", "html": "<p>Although JIT is fashionable today, some people would say it hasn&#x27;t proved so successful in the service sector as it has with the manufacturing of goods that can be <u>quantified</u>. That would be interesting. I&#x27;ll see what I can find out.</p>", "start": null}, {"id": "s3-t11", "text": "Before you hear the rest of the discussion, you have some time to look at questions 25 to 30. Now listen and answer questions 25 to 30. Now, unless you have any more questions, let's turn to a critique of the technical aspects of the presentation.", "html": "<p>Before you hear the rest of the discussion, you have some time to look at questions 25 to 30. Now listen and answer questions 25 to 30. Now, unless you have any more questions, let&#x27;s turn to <i>a critique of the technical aspects of the presentation</i>.</p>", "start": null}, {"id": "s3-t12", "text": "I'm afraid I'll emphasise the things I think you might want to work on. It was a good talk, but with a little work, your next presentation should be excellent. Fine.", "html": "<p>I&#x27;m afraid I&#x27;ll emphasise the things I think you might want to work on. It was a good talk, but with a little work, your next presentation should be excellent. Fine.</p>", "start": null}, {"id": "s3-t13", "text": "That would be helpful. Actually, I wasn't happy with my delivery. I Q25 sometimes seemed to talk fast and sometimes slow.", "html": "<p>That would be helpful. Actually, I wasn&#x27;t happy with <i>my delivery</i>. I Q25 <u>sometimes</u> seemed to <u>talk fast</u> and <u>sometimes slow</u>.</p>", "start": null}, {"id": "s3-t14", "text": "I was on edge, I guess. Yes, you were. And as well as that, Q26 your purpose wasn't very specific.", "html": "<p>I was on edge, I guess. Yes, you were. And as well as that, Q26 <i>your purpose</i> <u>wasn&#x27;t very specific</u>.</p>", "start": null}, {"id": "s3-t15", "text": "In future, you need to lay out exactly what you're going to cover and why. Make it clear and concise and not so general. And what about my transitions from one section to the next?", "html": "<p>In future, you need to lay out exactly what you&#x27;re going to cover and why. Make it clear and concise and <u>not so general</u>. And what about <i>my transitions from one section to the next</i>?</p>", "start": null}, {"id": "s3-t16", "text": "Well, you didn't link the sections, did you? Q27 You went too quickly from one to the next. It was all just too abrupt.", "html": "<p>Well, you didn&#x27;t link the sections, did you? Q27 You went <u>too quickly</u> from one to the next. It was all just <u>too abrupt</u>.</p>", "start": null}, {"id": "s3-t17", "text": "Okay, I'll try to improve that. Now, your PowerPoint visuals were lovely, but sometimes I got the feeling that, nice as they were as pictures, Q28 they didn't have much to do with what you were talking about, right? You're right.", "html": "<p>Okay, I&#x27;ll try to improve that. Now, <i>your PowerPoint visuals</i> were lovely, but sometimes I got the feeling that, nice as they were as pictures, Q28 they <u>didn&#x27;t have much to do with</u> what you were talking about, right? You&#x27;re right.</p>", "start": null}, {"id": "s3-t18", "text": "And, you know, another thing, I could see from the other students' reactions, Q29 they just didn't understand some of the vocabulary I was using. Good point. Well, remember, your audience were laymen, mostly without knowledge of JIT.", "html": "<p>And, you know, another thing, I could see from the other students&#x27; reactions, Q29 they <u>just didn&#x27;t understand some of the</u> <i>vocabulary</i> I was using. Good point. Well, remember, your audience were <u>laymen</u>, mostly without knowledge of JIT.</p>", "start": null}, {"id": "s3-t19", "text": "So, you need to simplify and try to put things in everyday English. I never seem to do that. And lastly, I'll just mention your body language.", "html": "<p>So, you need to <u>simplify</u> and try to put things in everyday English. I never seem to do that. And lastly, I&#x27;ll just mention <i>your body language</i>.</p>", "start": null}, {"id": "s3-t20", "text": "Q30 You didn't use gestures and you just stood straight without any animation. It didn't make you seem very interested in the subject. I know, even though I really do like the subject.", "html": "<p>Q30 You <u>didn&#x27;t use gestures</u> and you <u>just stood straight without any animation</u>. It <u>didn&#x27;t make you seem very interested in the subject</u>. I know, even though I really do like the subject.</p>", "start": null}, {"id": "s3-t21", "text": "Sorry. Well, despite all this, I enjoyed your presentation and I could see you put lots of work into it. I look forward to an even better presentation from you next time.", "html": "<p>Sorry. Well, despite all this, I enjoyed your presentation and I could see you put lots of work into it. I look forward to an even better presentation from you next time.</p>", "start": null}, {"id": "s3-t22", "text": "Well, thanks for your help. That is the end of part three. You now have 30 seconds to check your answers to part three.", "html": "<p>Well, thanks for your help. That is the end of part three. You now have 30 seconds to check your answers to part three.</p>", "start": null}], "4": [{"id": "s4-t1", "text": "In part four, you will hear about studying Dyscalculia, a neurodevelopmental disorder affecting numerical abilities. First, you have some time to look at questions 31 to 40. Now, listen carefully and answer questions 31 to 40.", "html": "<p>In part four, you will hear about studying Dyscalculia, a neurodevelopmental disorder affecting numerical abilities. First, you have some time to look at questions 31 to 40. Now, listen carefully and answer questions 31 to 40.</p>", "start": null}, {"id": "s4-t2", "text": "Dyscalculia, a complex neurodevelopmental condition, refers to a learning disorder marked by significant challenges in understanding and manipulating numerical concepts, quantities, and mathematical operations. It's a condition that affects children's ability to understand and work with numbers. Currently, most schools use the Q31 traditional method of teaching mathematics, which may not be effective for children with Dyscalculia.", "html": "<p>Dyscalculia, a complex neurodevelopmental condition, refers to a learning disorder marked by significant challenges in understanding and manipulating numerical concepts, quantities, and mathematical operations. It&#x27;s a condition that affects children&#x27;s ability to understand and work with numbers. Currently, most schools use the Q31 <u>traditional</u> <i>method of teaching</i> mathematics, which may not be effective for children with Dyscalculia.</p>", "start": null}, {"id": "s4-t3", "text": "These children struggle with grasping mathematical concepts, especially when it comes to understanding the concept of Q32 time and sequence. They find it challenging to comprehend the passage of time and the order in which events occur. In the classroom, teachers focus on providing everyday practical examples to help these children overcome their difficulties.", "html": "<p>These children <i>struggle with</i> grasping mathematical concepts, especially when it comes <i>to understanding the concept of</i> Q32 <u>time</u> and <i>sequence</i>. They find it challenging to comprehend the passage of time and the order in which events occur. In the classroom, teachers focus on providing everyday practical examples to help these children overcome their difficulties.</p>", "start": null}, {"id": "s4-t4", "text": "They engage the students in activities that involve dealing with Q33 money, as this is a common challenge for children with Dyscalculia. By incorporating real-life scenarios, teachers aim to make the learning experience more meaningful and relatable for these students. Additionally, teachers provide individualised support and interventions tailored to each student's needs.", "html": "<p>They engage the students in activities that involve <i>dealing with</i> Q33 <u>money</u>, as this is <i>a common challenge for children</i> with Dyscalculia. By incorporating real-life scenarios, teachers aim to make the learning experience more meaningful and relatable for these students. Additionally, teachers provide individualised support and interventions tailored to each student&#x27;s needs.</p>", "start": null}, {"id": "s4-t5", "text": "To boost their Q34 confidence, children with mathematics disorders are encouraged to practise more calculations and problem-solving. This additional practise helps them develop a stronger sense of self-assurance when it comes to dealing with mathematical tasks. Teachers also provide positive reinforcement and praise for their efforts and progress.", "html": "<p><i>To boost their</i> Q34 <u>confidence</u>, children with mathematics disorders are encouraged to <i>practise more calculations</i> and problem-solving. This additional practise helps them develop a stronger sense of <i>self-assurance</i> when it comes to dealing with mathematical tasks. Teachers also provide positive reinforcement and praise for their efforts and progress.</p>", "start": null}, {"id": "s4-t6", "text": "Teachers also implement strategies that encourage children to make educated Q35 guesses when they encounter mathematical problems. By empowering them to make informed guesses, teachers hope to foster problem-solving skills and reduce anxiety associated with mathematical challenges. Additionally, they incorporate various exercises, such as breathing techniques, relaxation exercises, and even Q36 walking breaks, to promote a conducive learning environment.", "html": "<p>Teachers also implement strategies that encourage children to make <i>educated</i> Q35 <u>guesses</u> when they encounter mathematical problems. By empowering them to make informed guesses, teachers hope to foster problem-solving skills and reduce anxiety associated with mathematical challenges. Additionally, they <i>incorporate various exercises</i>, such as <i>breathing techniques, relaxation exercises</i>, and even Q36 <u>walking</u> breaks, to promote a conducive learning environment.</p>", "start": null}, {"id": "s4-t7", "text": "These activities aid in reducing stress and promoting focus during math lessons. Teachers also explore alternative teaching methods, such as visual aids and manipulatives, to enhance understanding and engagement. Researchers in this field are particularly interested in finding a potential Q37 link between Dyscalculia and language learning difficulties.", "html": "<p>These activities aid in reducing stress and promoting focus during math lessons. Teachers also explore alternative teaching methods, such as visual aids and manipulatives, to enhance understanding and engagement. <i>Researchers</i> in this field <i>are particularly interested in finding a</i> potential Q37 <u>link</u> between Dyscalculia and <i>language learning difficulties</i>.</p>", "start": null}, {"id": "s4-t8", "text": "They are investigating whether there is a connection between language barriers and the challenges children face in mathematics. Understanding this link could help inform more targeted interventions and support strategies. Children with Dyscalculia often struggle with Q38 concentration and maintaining focus.", "html": "<p>They are investigating whether there is a connection between language barriers and the challenges children face in mathematics. Understanding this link could help inform more targeted interventions and support strategies. Children with Dyscalculia often <i>struggle with</i> Q38 <u>concentration</u> and <i>maintaining focus</i>.</p>", "start": null}, {"id": "s4-t9", "text": "Teachers are aware of this issue and work to provide additional support and accommodations to help these children stay engaged during lessons. They may use techniques like chunking information, breaking tasks into smaller steps, and providing regular breaks. With this comprehensive approach to teaching children with Dyscalculia, the aim is to provide them with the necessary skills and strategies to overcome their mathematical challenges.", "html": "<p>Teachers are aware of this issue and work to provide additional support and accommodations to help these children stay engaged during lessons. They may use techniques like chunking information, breaking tasks into smaller steps, and providing regular breaks. With this comprehensive approach to teaching children with Dyscalculia, the aim is to provide them with the necessary skills and strategies to overcome their mathematical challenges.</p>", "start": null}, {"id": "s4-t10", "text": "By implementing these strategies, children may no longer require Q39 additional treatment or training specifically focused on their mathematics disorder. Ongoing assessment and monitoring of progress are crucial to ensure the effectiveness of interventions and make any necessary adjustments. It's important to note that Dyscalculia affects not only the children, but also their families and Q40 teachers.", "html": "<p><i>By implementing these strategies</i>, children <i>may no longer require</i> Q39 <u>additional</u> treatment or <i>training</i> specifically focused on their mathematics disorder. Ongoing assessment and monitoring of progress are crucial to ensure the effectiveness of interventions and make any necessary adjustments. It&#x27;s important to note that Dyscalculia <i>affects not only</i> the children, <i>but also</i> their families and Q40 <u>teachers</u>.</p>", "start": null}, {"id": "s4-t11", "text": "Teachers and families play a crucial role in supporting these children and understanding their unique needs in the classroom and at home. Open communication, collaboration, and a supportive environment are key in helping children with Dyscalculia thrive academically and emotionally. By recognising and addressing Dyscalculia, we can provide a more inclusive and supportive learning environment for all students.", "html": "<p>Teachers and families play a crucial role in supporting these children and understanding their unique needs in the classroom and at home. Open communication, collaboration, and a supportive environment are key in helping children with Dyscalculia thrive academically and emotionally. By recognising and addressing Dyscalculia, we can provide a more inclusive and supportive learning environment for all students.</p>", "start": null}, {"id": "s4-t12", "text": "That is the end of Part 4. You now have one minute to check your answers to Part 4.", "html": "<p>That is the end of Part 4. You now have one minute to check your answers to Part 4.</p>", "start": null}]}, "transcripts": {"1": "<p>You will hear a number of different recordings, and you will have to answer questions on what you hear. There will be time for you to read the instructions and questions, and you will have a chance to check your work. All the recordings will be played once only.</p><p>The test is in four parts. Write all your answers in the listening question booklet. At the end of the test, you will be given 10 minutes to transfer your answers to an answer sheet.</p><p>Now turn to part 1 on page 2 of your question booklet. Part 1 You will hear a conversation between a travel agent and a student who is planning a trip abroad. First, you have some time to look at questions 1 to 6.</p><p>Now listen carefully and answer questions 1 to 6. Hello, how can I help you? I&#x27;m taking a year off and I&#x27;m hoping to travel abroad and to find work as well for part of the time.</p><p>I know you specialise in student travel and work placement, so... That&#x27;s right, we can help you arrange your travel and set up a job for you. But first of all, I need some personal details, and then we&#x27;ll match your details against our database to see what&#x27;s available work-wise.</p><p>Great. OK, your full name? Sarah Brown.</p><p>Date of birth? Q1 <u>March the 30th</u>. Oh, I&#x27;m the 31st!</p><p><u>1988</u>. And your address? 21 Waverley Road, Radstone RD46WV.</p><p>And a contact telephone number, please. I can give you my mobile number. Q2 <u>0903 775 115</u>.</p><p>Fine. Now, tell me where you plan to travel to and I&#x27;ll see how I can help. Well, I&#x27;d like to go to Q3 <u>Northern</u> Europe.</p><p>Have you been there before? No, I know <u>Southern Europe</u> quite well as I&#x27;ve been there with my family. We always went by plane, but now I can choose.</p><p>I&#x27;d like to go by Q4 <u>train</u> so I can stop off whenever I want. OK. Now, just as important, what sort of work have you got in mind?</p><p>Well, I thought about Q5 <u>hotel</u> work because then I might get accommodation with the job and I&#x27;d like to work for about half the year. That sort of work is usually quite competitive. Perhaps you should consider an alternative just in case.</p><p>Such as? Well, lots of students like to work on a Q6 <u>farm</u> and we have lots of requests from people looking for student workers for a few weeks at a time throughout the year. You can generally earn quite good money if you&#x27;re willing to work fairly long hours.</p><p>Before you hear the rest of the conversation, you have some time to look at questions 7 to 10. Now listen and answer questions 7 to 10. Now, travel.</p><p>Buying single tickets would be expensive so the best option would be to have a Q7 <u>European</u> pass which would give you unlimited rail travel at off-peak times. To start off with, we could issue one for up to three months to cover the countries you&#x27;re intending to visit. Sounds good.</p><p>Do you have any information about youth hostels which I could use to plan my route? Yes, I&#x27;ll give you a Q8 <u>booklet</u> now. But it&#x27;s down to you to book your accommodation.</p><p>At certain times of the year, especially during public holiday periods, such places fill up fast. And remember, if we&#x27;re going to arrange work for you in the countryside, you won&#x27;t be able to go out easily in the evenings. Although you&#x27;d probably be too tired anyway.</p><p>I won&#x27;t mind that. And you&#x27;re going to be travelling alone? Yes.</p><p>Well, before I make any arrangements for you, you need to have Q9 <u>insurance</u> for your entire trip. We can arrange that for you if you like. What does it cover?</p><p>Any valuable items, jewellery for example, your money, your mobile, your health, and if you needed to get back home quickly, you&#x27;d be covered so you could buy a plane ticket. Right, I&#x27;ll do that. I thought I&#x27;d take my laptop so I can email and keep in touch with people at home.</p><p>Not a good idea to lug your computer around with you. It&#x27;s much more sensible to rely on an Q10 <u>internet cafe</u>. That&#x27;s what we tell people to do.</p><p>Oh, OK. Right, so I&#x27;ve entered all your details, let&#x27;s see what the database comes up with. That is the end of part one. You now have one minute to check your answers to part one.</p>", "2": "<p>Part two. You will hear the manager of a bookshop called Bibliostack talking to a group of young people about the way the bookshop is organised.</p><p>First, you have some time to look at questions 11 to 15. Now listen carefully and answer questions 11 to 15. Good morning, everyone, and a big welcome to Bibliostack.</p><p>Firstly, I&#x27;ll explain the plan of the store to you. The building is on seven floors and is circular, as you can see, and we&#x27;re here on the ground floor in its entrance hall. Q11 Right in the centre of this floor, but behind the bookshelf so you can&#x27;t see it very well from here, is our main <i>seating area</i>, where people are encouraged to sit and read for as long as they like.</p><p>But they&#x27;re under no pressure to buy what they&#x27;re reading. That&#x27;s not how we operate. And if you look Q12 to your immediate left, past the first double row of shelves, you&#x27;ll see piles of coloured <i>cushions</i> in front of the window there.</p><p>We provide those so that people can sit wherever they want. Lots of people like to sit close to the bookshelves, and if they want to sit on the floor there, we want them to be as comfortable as possible. Q13 On your right, between the two larger bookshelves, you&#x27;ll see the <i>computer bench</i>, where our visitors can search through our entire catalogue.</p><p>We pride ourselves in being the largest bookshop in the country, so our sales assistants can&#x27;t possibly know all the available titles. Although the room in front of you is dominated by the bookshelves, Q14 at the far end, just in front of the lift, you&#x27;ll see that we provide a small <i>cafe bar</i> here too. And just to your right, there&#x27;s a door to the cloakroom, where people can leave their coats.</p><p>Then after that, Q15 there&#x27;s a stand where we keep a selection of local and national <i>newspapers</i>. Customers are welcome to browse through them, and we also have some for sale. We really want people to feel as though they&#x27;re browsing through books in the comfort of their own home.</p><p>Before you hear the rest of the talk, you have some time to look at questions 16 to 20. Now listen and answer questions 16 to 20. Right, now I suggest we walk slowly up through the building, and I&#x27;ll give you more information as we go.</p><p>We&#x27;re open 12 hours a day. We don&#x27;t mind if people spend the whole day here, but leave without buying anything. Of course, we hope they&#x27;ll buy something, but Q16 <i>our purpose is</i> <u>to draw people in</u>, to provide the kind of environment which <u>makes them want to stay and read</u>.</p><p>Look at how busy each floor is, but how quiet. You may be wondering whether there are any children in the building. We debated about <i>locating children&#x27;s books</i> on the ground floor, or halfway up the building, like the third or fourth floor, but in the end, Q17 we decided to put them <u>on the very top level</u>, and I can assure you it&#x27;s not the least bit quiet up there.</p><p>Of course, many parents would prefer to spend time on other floors, and so we provide a supervised area for children under two in the basement, so parents can wander around the shop for a few hours and not worry. But they do have to pay for this service, because although we thought about using some of our own assistants, Q18 we decided to employ <u>qualified nursery staff</u> for <i>parents&#x27; complete peace of mind</i>. Now, we&#x27;re just passing the fiction section, and you&#x27;ve probably noticed a small crowd of people beginning to gather.</p><p>That&#x27;s because a well-known author is going to read from her latest novel. We try to hold events like this at least once or twice a week, and as you can imagine, they&#x27;re very popular. We don&#x27;t make a charge for people to attend, but Q19 we obviously hope that some of them will want to <u>purchase the book</u> after listening to part of it being read aloud.</p><p>Other events which are proving to be very popular are our workshops. Last week, we held a <i>poetry workshop</i>, and people came along with poems that they&#x27;d written. One of the country&#x27;s best-known poets ran the workshop, and Q20 the participants <u>read their poems aloud</u> to him.</p><p>He was kind and encouraging, and many people felt inspired by his advice. It&#x27;s extremely difficult to earn your living as a professional poet, and even published poets have other jobs. Now, we&#x27;re going to take a look at our section on audiobooks.</p><p>That is the end of part two. You now have 30 seconds to check your answers to part two.</p>", "3": "<p>Part three. You will hear a business student called Ron getting feedback from his tutor on his presentation. First, you have some time to look at questions 21 to 24. Now listen carefully and answer questions 21 to 24.</p><p>Thanks, Ron, for coming to my office to discuss the presentation you gave yesterday to the business management seminar. We&#x27;ll go over what you did with the aim of helping you improve your next presentation. Sounds good.</p><p>Now, the topic was the just-in-time, or JIT, supply system used by a lot of manufacturers, first in Japan and then in the West, I think. Yes, but actually Q21 one thing I should have <u>made clearer and talked about was the fact that the Americans actually pioneered the idea</u> of just-in-time, though it wasn&#x27;t called that. Henry Ford and his cars, in fact, at the turn of the 20th century.</p><p>And later, a big US supermarket chain used it, and this was where Toyota in Japan got the idea for its car making. Yes, that would have been a good addition. Now, before we go any further, I think I would suggest that Q22 you should have stopped and <u>clearly defined</u> just-in-time for your seminar colleagues.</p><p>You said its aim was to reduce waste, and you mentioned that classic business theory assumes that stock, or inventory of parts, are counted as assets, but just-in-time sees them as unnecessary waste. But you never told us that JIT simply means waiting until the last moment to order new supplies as you need them. Yes, you&#x27;re right.</p><p>I should have done that. Now, you talked a bit about standardising parts as a way of streamlining JIT. Where did you get your data from?</p><p>Well, I tried an internet website on the subject which is called The Lean Clearinghouse, but it was too technical for me. So, Q23 in the end, I got my data from <u>a textbook</u> called Learning from Toyota. I found some journal articles too, but they didn&#x27;t seem very useful.</p><p>Yes, well, there is a US government report on it I&#x27;ve seen. I&#x27;ll get a copy for you. Great.</p><p>I look forward to reading through it. And while you&#x27;re at it, you might want to find out about cases where JIT might not be suitable. And that&#x27;s in <i>service industries</i> like tourism or healthcare, where Q24 customers are paying for something that they <u>can&#x27;t actually see or count</u>.</p><p>Although JIT is fashionable today, some people would say it hasn&#x27;t proved so successful in the service sector as it has with the manufacturing of goods that can be <u>quantified</u>. That would be interesting. I&#x27;ll see what I can find out.</p><p>Before you hear the rest of the discussion, you have some time to look at questions 25 to 30. Now listen and answer questions 25 to 30. Now, unless you have any more questions, let&#x27;s turn to <i>a critique of the technical aspects of the presentation</i>.</p><p>I&#x27;m afraid I&#x27;ll emphasise the things I think you might want to work on. It was a good talk, but with a little work, your next presentation should be excellent. Fine.</p><p>That would be helpful. Actually, I wasn&#x27;t happy with <i>my delivery</i>. I Q25 <u>sometimes</u> seemed to <u>talk fast</u> and <u>sometimes slow</u>.</p><p>I was on edge, I guess. Yes, you were. And as well as that, Q26 <i>your purpose</i> <u>wasn&#x27;t very specific</u>.</p><p>In future, you need to lay out exactly what you&#x27;re going to cover and why. Make it clear and concise and <u>not so general</u>. And what about <i>my transitions from one section to the next</i>?</p><p>Well, you didn&#x27;t link the sections, did you? Q27 You went <u>too quickly</u> from one to the next. It was all just <u>too abrupt</u>.</p><p>Okay, I&#x27;ll try to improve that. Now, <i>your PowerPoint visuals</i> were lovely, but sometimes I got the feeling that, nice as they were as pictures, Q28 they <u>didn&#x27;t have much to do with</u> what you were talking about, right? You&#x27;re right.</p><p>And, you know, another thing, I could see from the other students&#x27; reactions, Q29 they <u>just didn&#x27;t understand some of the</u> <i>vocabulary</i> I was using. Good point. Well, remember, your audience were <u>laymen</u>, mostly without knowledge of JIT.</p><p>So, you need to <u>simplify</u> and try to put things in everyday English. I never seem to do that. And lastly, I&#x27;ll just mention <i>your body language</i>.</p><p>Q30 You <u>didn&#x27;t use gestures</u> and you <u>just stood straight without any animation</u>. It <u>didn&#x27;t make you seem very interested in the subject</u>. I know, even though I really do like the subject.</p><p>Sorry. Well, despite all this, I enjoyed your presentation and I could see you put lots of work into it. I look forward to an even better presentation from you next time.</p><p>Well, thanks for your help. That is the end of part three. You now have 30 seconds to check your answers to part three.</p>", "4": "<p>In part four, you will hear about studying Dyscalculia, a neurodevelopmental disorder affecting numerical abilities. First, you have some time to look at questions 31 to 40. Now, listen carefully and answer questions 31 to 40.</p><p>Dyscalculia, a complex neurodevelopmental condition, refers to a learning disorder marked by significant challenges in understanding and manipulating numerical concepts, quantities, and mathematical operations. It&#x27;s a condition that affects children&#x27;s ability to understand and work with numbers. Currently, most schools use the Q31 <u>traditional</u> <i>method of teaching</i> mathematics, which may not be effective for children with Dyscalculia.</p><p>These children <i>struggle with</i> grasping mathematical concepts, especially when it comes <i>to understanding the concept of</i> Q32 <u>time</u> and <i>sequence</i>. They find it challenging to comprehend the passage of time and the order in which events occur. In the classroom, teachers focus on providing everyday practical examples to help these children overcome their difficulties.</p><p>They engage the students in activities that involve <i>dealing with</i> Q33 <u>money</u>, as this is <i>a common challenge for children</i> with Dyscalculia. By incorporating real-life scenarios, teachers aim to make the learning experience more meaningful and relatable for these students. Additionally, teachers provide individualised support and interventions tailored to each student&#x27;s needs.</p><p><i>To boost their</i> Q34 <u>confidence</u>, children with mathematics disorders are encouraged to <i>practise more calculations</i> and problem-solving. This additional practise helps them develop a stronger sense of <i>self-assurance</i> when it comes to dealing with mathematical tasks. Teachers also provide positive reinforcement and praise for their efforts and progress.</p><p>Teachers also implement strategies that encourage children to make <i>educated</i> Q35 <u>guesses</u> when they encounter mathematical problems. By empowering them to make informed guesses, teachers hope to foster problem-solving skills and reduce anxiety associated with mathematical challenges. Additionally, they <i>incorporate various exercises</i>, such as <i>breathing techniques, relaxation exercises</i>, and even Q36 <u>walking</u> breaks, to promote a conducive learning environment.</p><p>These activities aid in reducing stress and promoting focus during math lessons. Teachers also explore alternative teaching methods, such as visual aids and manipulatives, to enhance understanding and engagement. <i>Researchers</i> in this field <i>are particularly interested in finding a</i> potential Q37 <u>link</u> between Dyscalculia and <i>language learning difficulties</i>.</p><p>They are investigating whether there is a connection between language barriers and the challenges children face in mathematics. Understanding this link could help inform more targeted interventions and support strategies. Children with Dyscalculia often <i>struggle with</i> Q38 <u>concentration</u> and <i>maintaining focus</i>.</p><p>Teachers are aware of this issue and work to provide additional support and accommodations to help these children stay engaged during lessons. They may use techniques like chunking information, breaking tasks into smaller steps, and providing regular breaks. With this comprehensive approach to teaching children with Dyscalculia, the aim is to provide them with the necessary skills and strategies to overcome their mathematical challenges.</p><p><i>By implementing these strategies</i>, children <i>may no longer require</i> Q39 <u>additional</u> treatment or <i>training</i> specifically focused on their mathematics disorder. Ongoing assessment and monitoring of progress are crucial to ensure the effectiveness of interventions and make any necessary adjustments. It&#x27;s important to note that Dyscalculia <i>affects not only</i> the children, <i>but also</i> their families and Q40 <u>teachers</u>.</p><p>Teachers and families play a crucial role in supporting these children and understanding their unique needs in the classroom and at home. Open communication, collaboration, and a supportive environment are key in helping children with Dyscalculia thrive academically and emotionally. By recognising and addressing Dyscalculia, we can provide a more inclusive and supportive learning environment for all students.</p><p>That is the end of Part 4. You now have one minute to check your answers to Part 4.</p>"}, "questionSegments": {"1": [], "2": ["s1-t9"], "3": ["s1-t10"], "4": ["s1-t11"], "5": ["s1-t13"], "6": ["s1-t14"], "7": ["s1-t16"], "8": [], "9": ["s1-t20"], "10": ["s1-t22"], "11": ["s2-t3"], "12": [], "13": ["s2-t5"], "14": [], "15": ["s2-t7"], "16": [], "17": ["s2-t10"], "18": ["s2-t11"], "19": [], "20": ["s2-t13"], "21": ["s3-t3"], "22": ["s3-t4"], "23": ["s3-t7"], "24": ["s3-t9"], "25": ["s3-t13"], "26": ["s3-t14"], "27": ["s3-t16"], "28": ["s3-t17"], "29": ["s3-t18"], "30": ["s3-t20"], "31": ["s4-t2"], "32": [], "33": ["s4-t4"], "34": ["s4-t5"], "35": ["s4-t6"], "36": ["s4-t6"], "37": [], "38": ["s4-t8"], "39": [], "40": []}, "headingsBySection": {}, "grading": {"pairs": [], "sets": []}, "groups": [[1, 10], [11, 20], [21, 30], [31, 40]], "questionTypes": {"1": "gap", "2": "gap", "3": "gap", "4": "gap", "5": "gap", "6": "gap", "7": "gap", "8": "gap", "9": "gap", "10": "gap", "11": "matching", "12": "matching", "13": "matching", "14": "matching", "15": "matching", "16": "single", "17": "single", "18": "single", "19": "single", "20": "single", "21": "single", "22": "single", "23": "single", "24": "single", "25": "matching", "26": "matching", "27": "matching", "28": "matching", "29": "matching", "30": "matching", "31": "gap", "32": "gap", "33": "gap", "34": "gap", "35": "gap", "36": "gap", "37": "gap", "38": "gap", "39": "gap", "40": "gap"}, "audioFiles": {"1": "1-International-Student-Travel-Agency.mp3", "2": "2-Bibliostack.mp3", "3": "3-The-Just-in-Time-Supply-System-JIT.mp3", "4": "4-Dyscalculia.mp3"}, "audio": {"1": "Listening - Vol 8/Test 1/audio/part-1.mp3", "2": "Listening - Vol 8/Test 1/audio/part-2.mp3", "3": "Listening - Vol 8/Test 1/audio/part-3.mp3", "4": "Listening - Vol 8/Test 1/audio/part-4.mp3"}, "sourceAnswerKey": {"1": ["30 March 1988", "30th March 1988", "March 30 1988", "March 30th 1988", "30/3/1988"], "2": ["0903775115"], "3": ["northern"], "4": ["train"], "5": ["hotel"], "6": ["farm"], "7": ["pass"], "8": ["booklet"], "9": ["insurance"], "10": ["internet cafe", "internet café"], "11": ["C"], "12": ["F"], "13": ["D"], "14": ["A"], "15": ["H"], "16": ["C"], "17": ["B"], "18": ["C"], "19": ["A"], "20": ["C"], "21": ["A"], "22": ["B"], "23": ["C"], "24": ["A"], "25": ["B"], "26": ["H"], "27": ["D"], "28": ["G"], "29": ["E"], "30": ["F"], "31": ["traditional"], "32": ["time"], "33": ["money"], "34": ["confidence"], "35": ["guesses"], "36": ["walking"], "37": ["link"], "38": ["concentration"], "39": ["additional"], "40": ["teachers"]}, "sourceNotes": [], "hasAnswerKey": true};
